bool verify_password(PgSocket *client, const char *passwd) {
    const char *stored_pass = client->auth_password;
    AuthType auth_type = client->auth_type;

    if (!passwd || *passwd == '\0' || !stored_pass || *stored_pass == '\0') {
        return false;
    }

    switch (auth_type) {
        case AUTH_PLAIN:
            return strcmp(passwd, stored_pass) == 0;

        case AUTH_CRYPT:
            {
                struct crypt_data data;
                memset(&data, 0, sizeof(data));
                char *encrypted = crypt_r(passwd, stored_pass + 2, &data);
                return encrypted && strcmp(encrypted, stored_pass) == 0;
            }

        case AUTH_MD5:
            {
                char *md5_prefix = "md5";
                if (strncmp(stored_pass, md5_prefix, strlen(md5_prefix)) != 0) {
                    return false;
                }

                unsigned char digest[MD5_DIGEST_LENGTH];
                MD5((unsigned char *)passwd, strlen(passwd), digest);
                char hash[3 * MD5_DIGEST_LENGTH + 1];
                for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
                    sprintf(hash + (i * 2), "%02x", digest[i]);
                }

                char expected[MD5_DIGEST_LENGTH * 2 + strlen(md5_prefix) + 1];
                snprintf(expected, sizeof(expected), "%s%s", md5_prefix, hash);

                return strcmp(expected, stored_pass) == 0;
            }

        default:
            return false;
    }
}

bool check_password(PgSocket *client, const char *passwd) {
    if (client->stored_password == NULL || passwd == NULL ||
        *client->stored_password == '\0' || *passwd == '\0') {
        return false;
    }

    if (strcmp(client->auth_method, "plain") == 0) {
        return strcmp(client->stored_password, passwd) == 0;
    } else if (strcmp(client->auth_method, "crypt") == 0) {
        char *encrypted = crypt(passwd, client->stored_password);
        return encrypted != NULL && strcmp(client->stored_password, encrypted) == 0;
    } else if (strcmp(client->auth_method, "md5") == 0) {
        if (strlen(passwd) == 0 || strlen(client->stored_password) != 32) {
            return false;
        }

        char salted_md5[35];
        snprintf(salted_md5, sizeof(salted_md5), "md5%s%s", client->salt, passwd);
        char *encrypted_md5 = md5_hash(salted_md5, strlen(salted_md5));
        return encrypted_md5 != NULL && strcmp(client->stored_password, encrypted_md5) == 0;
    }

    return false;
}

